INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_challenge#2','kor',1,1,'u7','L06','g1_1_kor_u7_L06_challenge','lesson_challenge','K1-1-u7-C7',2,'mc','auto','「무엇을」이 빠진 문장은 어느 것인가요?',ARRAY['K1-1-u7-X10']::text[],false,'{"seq":2,"concept":"K1-1-u7-C7","difficulty":2,"kind":"mc","stem":"「무엇을」이 빠진 문장은 어느 것인가요?","options":[{"t":"고양이가 마십니다.","correct":true},{"t":"고양이가 우유를 마십니다.","mis":"K1-1-u7-X10"},{"t":"고양이가 물을 마십니다.","mis":"K1-1-u7-X10"}],"explanation":["「고양이가 마십니다」는 무엇을 마시는지 없어요.","다른 두 문장에는 「우유를」·「물을」이 있어요.","「무엇을?」 하고 되물어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_challenge#3','kor',1,1,'u7','L06','g1_1_kor_u7_L06_challenge','lesson_challenge','K1-1-u7-C6',3,'mc','auto','같은 무리끼리 바르게 말한 문장은 어느 것인가요?',ARRAY['K1-1-u7-X08']::text[],false,'{"seq":3,"concept":"K1-1-u7-C6","difficulty":3,"kind":"mc","stem":"같은 무리끼리 바르게 말한 문장은 어느 것인가요?","options":[{"t":"포도와 배는 과일입니다.","correct":true},{"t":"포도와 오이는 과일입니다.","mis":"K1-1-u7-X08"},{"t":"포도와 배는 채소입니다.","mis":"K1-1-u7-X08"}],"explanation":["포도와 배는 둘 다 과일이에요.","오이는 채소이고, 포도와 배는 채소가 아니에요.","두 낱말이 모두 그 무리에 드는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
