INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u7_L06_challenge#5','kor',1,1,'u7','L06','g1_1_kor_u7_L06_challenge','lesson_challenge','K1-1-u7-C7',3,'error','auto','다람쥐가 도토리를 먹는 그림을 보고 이렇게 썼어요.
