INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u5_L08_challenge#3','math',1,1,'u5','L08','g1_1_math_u5_L08_challenge','lesson_challenge','M1-1-u5-C6',3,'mc','auto','34부터 거꾸로 세어 다섯째로 말하는 수는 무엇인가요?',ARRAY['M1-1-u5-X13','M1-1-u5-X10']::text[],true,'{"seq":3,"concept":"M1-1-u5-C6","difficulty":3,"kind":"mc","stem":"34부터 거꾸로 세어 다섯째로 말하는 수는 무엇인가요?","options":[{"t":"30","correct":true},{"t":"29","mis":"M1-1-u5-X13"},{"t":"38","mis":"M1-1-u5-X10"}],"explanation":["34부터 거꾸로 세어요.","34, 33, 32, 31, 30 — 다섯째는 30이에요.","첫째가 34라는 것을 잊지 않아요."],"variant_rule":{"alt":[{"stem":"27부터 거꾸로 세어 넷째로 말하는 수는 무엇인가요?","options":[{"t":"24","correct":true},{"t":"23","mis":"M1-1-u5-X13"},{"t":"30","mis":"M1-1-u5-X10"}],"explanation":["27부터 거꾸로 세어요.","27, 26, 25, 24 — 넷째는 24예요.","첫째가 27이라는 것을 잊지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
